9	/**
10	 * The array tuple to determine how cache will be built.
11	 *
12	 * - If only `Type` is given, the cache key should be resolved as `${valueof Type}:#`.
13	 * - If both parameters are given, the cache key will be built dynamically by executing
14	 * the second element (which is a function) by passing current calling arguments:
15	 * `${valueof Type}:${valueof CacheKey(...args)}`.
16	 *
17	 * @template Args The function arguments for the cache key builder to resolve.
18	 * @template Type The {@link WellKnownCacheType cache type}.
19	 */
20	type CacheKeyConfig<
21	  Args extends unknown[],
22	  Type extends string,
23	  CacheKey = (...args: Args) => string,
24	> = [Type] | [Type, CacheKey];
