26	export abstract class BaseCache<CacheMapT extends Record<string, unknown>> {
27	  static defaultKey = '#';
28	
29	  /**
30	   * For logging and debugging purposes only.
31	   * This name will be used in the log messages.
32	   */
33	  abstract name: string;
34	
35	  /**
36	   * @param tenantId The tenant ID this cache is intended for.
37	   * @param cacheStore The storage to use as the cache.
38	   */
39	  constructor(
40	    public tenantId: string,
41	    protected cacheStore: CacheStore
42	  ) {}
