44	  /**
45	   * Get value from the inner cache store for the given type and key.
46	   * Note: Redis connection and format errors will be silently caught and result an `undefined` return.
47	   */
48	  async get<Type extends CacheKeyOf<CacheMapT>>(
49	    type: Type,
50	    key: string
51	  ): Promise<Optional<CacheMapT[Type]>> {
52	    return trySafe(async () => {
53	      const data = await this.cacheStore.get(this.cacheKey(type, key));
54	      return this.getValueGuard(type).parse(JSON.parse(data ?? ''));
55	    });
56	  }
57	
58	  /**
59	   * Set value to the inner cache store for the given type and key.
60	   * The given value will be stringify without format validation before storing into the cache.
61	   *
62	   * @param expire The expire time in seconds. If not given, use the default expire time  30 * 60 seconds.
63	   */
64	  async set<Type extends CacheKeyOf<CacheMapT>>(
65	    type: Type,
66	    key: string,
67	    value: Readonly<CacheMapT[Type]>,
68	    expire?: number
69	  ) {
70	    return this.cacheStore.set(this.cacheKey(type, key), JSON.stringify(value), expire);
71	  }
72	
73	  /** Delete value from the inner cache store for the given type and key. */
74	  async delete(type: CacheKeyOf<CacheMapT>, key: string) {
75	    return this.cacheStore.delete(this.cacheKey(type, key));
76	  }
77	
78	  /**
79	   * Create a wrapper of the given function, which invalidates a set of keys in cache
80	   * after the function runs successfully.
81	   *
82	   * @param run The function to wrap.
83	   * @param types An array of {@link CacheKeyConfig}.
84	   */
85	  mutate<Args extends unknown[], Return>(
86	    run: (...args: Args) => Promise<Return>,
87	    ...types: Array<CacheKeyConfig<Args, CacheKeyOf<CacheMapT>>>
88	  ) {
89	    // Intended. We're going to use `this` cache inside another closure.
90	    // eslint-disable-next-line @typescript-eslint/no-this-alias, unicorn/no-this-assignment
91	    const kvCache = this;
92	
93	    const mutated = async function (this: unknown, ...args: Args): Promise<Return> {
94	      const value = await run.apply(this, args);
95	
96	      // We don't leverage `finally` here since we want to ensure cache deleting
97	      // only happens when the original function executed successfully
98	      void Promise.all(
99	        types.map(async ([type, cacheKey]) =>
100	          trySafe(kvCache.delete(type, cacheKey?.(...args) ?? BaseCache.defaultKey))
101	        )
102	      );
103	
104	      return value;
105	    };
106	
107	    return mutated;
108	  }
109	
110	  /**
111	   * [Memoize](https://en.wikipedia.org/wiki/Memoization) a function and cache the result. The function execution
112	   * will be also cached, which means there will be only one execution at a time.
113	   *
114	   * @param run The function to memoize.
115	   * @param config The object to determine how cache key will be built. See {@link CacheKeyConfig} for details.
116	   * @param getExpiresIn A function to determine how long the cache will be expired. The function will be called
117	   * with the resolved value from the original function. The return value should be the expire time in seconds.
118	   */
119	  memoize<
120	    Type extends CacheKeyOf<CacheMapT>,
121	    Args extends unknown[],
122	    Value extends Readonly<CacheMapT[Type]>,
123	  >(
124	    run: (...args: Args) => Promise<Value>,
125	    [type, cacheKey]: CacheKeyConfig<Args, Type>,
126	    getExpiresIn?: (value: Value) => number
127	  ) {
128	    const promiseCache = new Map<unknown, Promise<Readonly<CacheMapT[Type]>>>();
129	    // Intended. We're going to use `this` cache inside another closure.
130	    // eslint-disable-next-line @typescript-eslint/no-this-alias, unicorn/no-this-assignment
131	    const kvCache = this;
132	
133	    const memoized = async function (
134	      this: unknown,
135	      ...args: Args
136	    ): Promise<Readonly<CacheMapT[Type]>> {
137	      const promiseKey = cacheKey?.(...args) ?? BaseCache.defaultKey;
138	      const cachedPromise = promiseCache.get(promiseKey);
139	
140	      if (cachedPromise) {
