174	  abstract getValueGuard<Type extends CacheKeyOf<CacheMapT>>(type: Type): ZodType<CacheMapT[Type]>;
175	
176	  protected cacheKey(type: CacheKeyOf<CacheMapT>, key: string) {
177	    return `${this.tenantId}:${type}:${key}`;
178	  }
